    import sys
    import math

    def can_solve(n, k):
        # Calculate the minimum number of problems Polycarp can solve in k days
        min_problems = k * (k + 1) // 2
        if n < min_problems:
            return False

        # Calculate the maximum number of problems Polycarp can solve in k days
        max_problems = 0
        current = 1
        for _ in range(k):
            max_problems += current
            current *= 2
        if n > max_problems:
            return False

        return True

    def find_solution(n, k):
        # Binary search to find the smallest possible value for the first day's problem count
        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if mid * (mid + 1) // 2 <= n:
                low = mid + 1
            else:
                high = mid

        # Check if the found value works
        current = low - 1
        total = 0
        result = []
        for i in range(k):
            result.append(current)
            total += current
            if i < k - 1:
                current = min(2 * current, n - total)

        return result

    def solve(n, k):
        if not can_solve(n, k):
            return "NO"
        else:
            result = find_solution(n, k)
            return "YES\n" + " ".join(map(str, result))

    # Read input
    n, k = map(int, sys.stdin.readline().split())

    # Solve the problem
    print(solve(n, k))

